// Rover beacon: a tall mast with a lamp that lights while any rover is within
// 20 m, and broadcasts it. Since nearest() returns the closest rover, "closest
// within 20 m" means "any within 20 m".
//
// Player's choices and assumptions, not facts about Mars:
//   - trigger distance 20 m (player's request)
//   - always on: the power source is the player's assumption (not modelled)
//   - mast height 4 m and lamp colours: design choices for "tall and bright"
// Facts that shaped the design (cited in the manifest): dust optical depth
// in the clear season and in the Jan 2022 storm (why tall and bright), and the
// thin sunlight and cold nights (why power is a labelled assumption).
import { read, nearest, spawn, pose, remove, state_set, signal_emit, log, fact_tier,
         POS_X, POS_Z, KIND_ROVER, SHAPE_CYLINDER, SHAPE_SPHERE, SHAPE_CONE,
         FACT_JEZERO_DUST_OPTICAL_DEPTH_BACKGROUND_MY36 } from "./host";

const TRIGGER_M: f32 = 20.0;   // player's choice
const MAST_H: f32 = 4.0;       // design choice ("tall"), not a Mars number

const SLOT_DIST: i32 = 0;
const SLOT_LIT: i32 = 1;
const SIG_NEAR: i32 = 200;     // 1 every tick while a rover is within 20 m
const SIG_DIST: i32 = 201;     // distance (m) to that rover, same ticks

const LOG_LIT: i32 = 40;       // value: 1 lamp switched on, 0 switched off
const LOG_DIST: i32 = 41;      // value: rover distance (m) when the lamp switched on
const LOG_TIER: i32 = 42;      // value: provenance tier of the dust fact

let mast: i32 = -1;
let cap: i32 = -1;
let lamp: i32 = -1;
let lit: i32 = -1;             // -1 until the first tick decides

function setLamp(on: i32): void {
  // Recolouring means spawn a new shape and remove the old one.
  const old = lamp;
  if (on == 1) {
    lamp = spawn(SHAPE_SPHERE, 0.8, 0.8, 0.8, 1.0, 0.75, 0.15);   // bright amber
  } else {
    lamp = spawn(SHAPE_SPHERE, 0.5, 0.5, 0.5, 0.15, 0.12, 0.10);  // dark lens
  }
  if (lamp >= 0) pose(lamp, 0.0, MAST_H + 0.4, 0.0, 0.0, 0.0);
  if (old >= 0) remove(old);
}

export function init(): void {
  mast = spawn(SHAPE_CYLINDER, 0.15, MAST_H, 0.15, 0.75, 0.75, 0.78);
  if (mast >= 0) pose(mast, 0.0, MAST_H * 0.5, 0.0, 0.0, 0.0);
  cap = spawn(SHAPE_CONE, 0.6, 0.35, 0.6, 0.2, 0.2, 0.22);
  if (cap >= 0) pose(cap, 0.0, MAST_H + 1.0, 0.0, 0.0, 0.0);
  setLamp(0);
  lit = 0;
  log(LOG_TIER, <f32>fact_tier(FACT_JEZERO_DUST_OPTICAL_DEPTH_BACKGROUND_MY36));
}

export function tick(dt: f32): void {
  const d = nearest(KIND_ROVER, read(POS_X), read(POS_Z));   // -1 if no rover exists
  const near: i32 = (d >= 0.0 && d <= TRIGGER_M) ? 1 : 0;

  state_set(SLOT_DIST, d);
  state_set(SLOT_LIT, <f32>near);

  if (near != lit) {
    lit = near;
    setLamp(near);
    log(LOG_LIT, <f32>near);
    if (near == 1) log(LOG_DIST, d);
  }

  // Re-emit every tick while it holds, so no listener misses it.
  if (near == 1) {
    signal_emit(SIG_NEAR, 1.0);
    signal_emit(SIG_DIST, d);
  }
}

